/bin/bash -lc "node --input-type=module <<'EOF'
import { createApp } from './src/server.js';
import http from 'node:http';
const app=createApp(); const server=http.createServer(app);
await new Promise(resolve=>server.listen(0,resolve)); const port=server.address().port;
const req=async(path, options={})=>{const res=await fetch("'`http://127.0.0.1:${port}${path}`,options); return {status:res.status, body:await res.text(), setCookie:res.headers.get('"'set-cookie')}};
console.log('unauth list', await req('/api/appointments'));
const signed=await req('/api/sign-in',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({patientId:'patient-a'})});
console.log('sign-in', signed.status, signed.body, signed.setCookie);
const cookie=signed.setCookie?.split(';')[0];
console.log('cross-patient detail', await req('/api/appointments/other-id',{headers:{cookie}}));
console.log('static index', await req('/'));
server.close();
EOF
npm start"

